quests[92706] = { id = 92706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Bruuz", description = "Calling all anglers!\n\nA giant shark has been circling the waters near the shipping dock, attacking sailors and small boats. Dockworkers have given it the nickname \"Bruuz\". A hefty reward will be given to whoever brings me its fin!\n\n-- Gazlowe", sourceObjective = "Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet.", progress = "What can I do for ya, {race}?", completion = "Finally, somebody killed that thing! Do you know how hard it is to get a crew in the water when everyone in town's crying \"Shark!\"all the time?\n\nI might just put that monster's fin into a soup for dinner tonight, just to have the last laugh.", sourceObjectiveStatus = "unverified-source-field" }
quests[92707] = { id = 92707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Giant in the Den", description = "Wrenched from its hulking corpse, the goliath's bracers are massive. Your whole arm, up to the shoulder, can fit through one without touching the sides.\n\nYou should bring these back to Hammerfall, as a warning. Drum Fel ought to know what he's up against.", sourceObjective = "Bring the Goliath's Wristguards to Drum Fel in Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[92708] = { id = 92708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grand Adventure", description = "The Windshapers have been hard at work trying to respond to the current crisis on Zephras Isle. We have made several surprising discoveries in our search for the missing wind spirits, and we are developing a plan of action that could help us gain the means to save the island.\n\nWe'll need strong young adventurer's like yourself for this to work however. Please, if you have a moment, let us speak on this further.", sourceObjective = "Listen to what Ayessa Dawnsinger has to say.", completion = "So now you see? There is a world of knowledge and untapped potential outside of Skywall. This will never stop being our home, but I've come to believe that the path to our salvation lies below. We must travel to Azeroth and gain the power and means to save Zephras Isle. This is the way.\n\nWill you have the courage to join us when the time comes?", sourceObjectiveStatus = "unverified-source-field" }
quests[92709] = { id = 92709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grand Adventure", description = "Your highborne lineage shines as clearly in your eyes as the sky above. You are one of us, and its youth like yourself that will help us save our home. But first, let me tell you more of our mission and plans here on Zephras... and beyond.", sourceObjective = "Listen to what Elaadrin Evengale in Valanaar has to say.", completion = "So do you now see? Rediscovering the ancient magic of our forebears is the key to unlocking the secrets of Zephras Isle and securing our future, but in order to save our home, we must rediscover what we've lost these past millennia.\n\nAzeroth is the key. The Kirin Tor will show us the way.\n\nWhile we make ready to leave, you should check in with the other members of the High Order here in Valanaar. Most of them have tasks that they could use help from one such as yourself to see completed.", sourceObjectiveStatus = "unverified-source-field" }
quests[92727] = { id = 92727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scholar", description = "Seeking knowledge is the primary mandate of the High Order, but this work has never been more dangerous than it is now on Zephras.\n\nOne of our scholars--Fillion Flamebreeze--was en route to the Shen'dar Highlands to gather data on the windborne magic that congregates in some areas there. Regrettably, he has not returned and we fear that something may have befallen him on the road.\n\nIf you can, please locate him for us. He was last seen on the road leading west from Valanaar towards Shen'dar Highlands.", sourceObjective = "Discover what became of Fillion Flamebreeze.", completion = "<The satchel lying before you has a few specks of what appears to be dried blood on the flap. Studying the stain you also notice that the flap also has a name embroidered onto it. It reads \"Fillion Flamebreeze\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[92741] = { id = 92741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Visitors", description = "The Shadowgale Forest is incredibly dangerous and is usually off limits to normal adventurers. In recent months there's been an explosion in the shriekling population and they've started to expand their territory outside the woods, which is a potential problem. I have an interest in the alchemical properties of shriekling talons, so a much-needed culling also presents an opportunity for scholarly gain.\n\nTravel to Shadowgale Forest and hunt the beasts. Bring me as many of their talons as you can.", sourceObjective = "Travel to Shadowgale Forest and collect 8 Shriekling Talons for Iaadaria Bitterwind in Valanaar.", progress = "The High Order does not make it a habit to employ themselves as simple trappers and game wardens, but when performing a service such as this can lead to scholarly gain, we are happy to engage in acts of community service.", completion = "That is quite the haul of talons you've brought me. I cannot wait to dig into this!\n\nThank you for your service to the High Order, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92742] = { id = 92742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Wells", description = "We must determine the source and nature of the poison corrupting this land. Let us begin with the groundwater under the farms in the area.\n\nGo to the Jansen Stead in the north and the Molsen Farm northwest of here, and collect samples from the wells there.", sourceObjective = "Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm.", progress = "Did you collect the samples?", completion = "Thank you. Let me see...", sourceObjectiveStatus = "unverified-source-field" }
quests[92743] = { id = 92743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conqueror's Crown", description = "As the strongest centaur clan in all the land, we deserve armaments with ferocity that matches our strength! \n\nWarug needs one most of all. A helm... no, a crown! A conqueror's crown! I heard legends of a fearsome conqueror across the seas. Go to a place they call the Badlands and seek out a crypt there. Return to me only when you have found the crown.\n\nDo this for me, and I will reveal the Magram's greatest strength.", sourceObjective = "Maintain your reputation with the Magram, and return a Conqueror's Crown from the Badlands to Warug in Magram Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[92744] = { id = 92744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murloc Gills", description = "The corruption affecting Westfall's crops may have seeped into the ocean as well. If the local fish are affected too, it could doom Stormwind to famine.\nCollect gills from the murlocs along the shoreline and bring them to me. Murlocs are quite hardy, but their physiology is extremely sensitive to contaminants. Any toxins in the seawater will be readily apparent in the gills you find.", sourceObjective = "Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", progress = "I hope the murlocs did not give you too much trouble?", completion = "I see... these gills appear to be healthy, for now. But we must not be complacent.", sourceObjectiveStatus = "unverified-source-field" }
quests[92745] = { id = 92745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The State of the Mines", description = "The well samples you collected contain toxic metals! If we do not put an end to this corruption quickly, it will be decades before crops can grow in this soil again.\nThe Defias have seized the mines of Westfall and use creatures as labor to strip their resources. Disrupt them by slaying their miners in the Jangolode Mine to the north, and the Gold Coast Quarry to the west.", sourceObjective = "Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry.", completion = "Well done, {name}. But I fear the source of the poison may lie somewhere else...", sourceObjectiveStatus = "unverified-source-field" }
quests[92747] = { id = 92747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonbrook Espionage", description = "Strange - the poison does not seem to originate from the mines you investigated.\n\nI am told the Deadmines under the town of Moonbrook are the largest, deepest mines of Westfall, but they have been abandoned since the First War. Could the Deadmines be active again?\n\nPlease travel to Moonbrook, {name}, and look for evidence of mining or industrial activity. This is the last lead we have!", sourceObjective = "Collect 8 Suspicious Industrial Supplies from Moonbrook.", progress = "Did you find anything?", completion = "What is all this?", sourceObjectiveStatus = "unverified-source-field" }
quests[92748] = { id = 92748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Consultation", description = "The supplies you found point to a massive industrial operation somewhere in the Deadmines. There's no question that this is the source of the toxins plaguing the farmland of Westfall. We need to stop it, quickly.\n\nWhatever's down there will be difficult to destroy. Go to the Dwarven District of Stormwind, and find an engineer who can supply us with some explosives.", sourceObjective = "Travel to the Dwarven District in Stormwind and find an engineer who can help.", completion = "Need something blown up?", sourceObjectiveStatus = "unverified-source-field" }
quests[92749] = { id = 92749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dynamite Plan", description = "Industrial sabotage? You've got my attention!\nWe'll start with some dynamite...", sourceObjective = "Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind.", progress = "Show me those explosives, {name}!", completion = "This is a great start! Now to tie it all together... and add a little extra zing...", sourceObjectiveStatus = "unverified-source-field" }
quests[92750] = { id = 92750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation at a Distance", description = "I assume you want a \"controlled\" explosion? Not as much fun, but a good choice if you want to keep all your limbs.\nI'm afraid I don't have a remote detonator - why don't you go check with the sneaky folks down at Stormwind Intelligence? They should be able to find us something.", sourceObjective = "Talk to someone in Stormwind Intelligence about acquiring a remote detonator.", completion = "Hmm... Looking for something specific, are you?", sourceObjectiveStatus = "unverified-source-field" }
quests[92751] = { id = 92751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation at a Distance", description = "You need something destroyed? Would this have anything to do with your activities in Moonbrook? Don't look surprised. SI:7 stays apprised of all that goes on in Stormwind's lands.\nIf you're planning to set off an explosion in the caves below Westfall, you'll want to be well outside beforehand. Take this remote detonator - it's a recent prototype from our own engineers.\nOh - and it would be best if you didn't mention my involvement to your elf friend.", sourceObjective = "Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind.", completion = "Great - that's the detonator we need!", sourceObjectiveStatus = "unverified-source-field" }
quests[92752] = { id = 92752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Consultation", description = "That's it - the bomb's ready to go! Careful with that detonator, now.", sourceObjective = "Return to Alba Fairmoon in Westfall.", completion = "I'm glad you've returned, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92753] = { id = 92753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destruction in Deadmines", description = "The source of the poison is likely a large metallurgical forge of some kind. Find a way into the Deadmines and locate the forge, then place the explosives.\nI will wait for you in the hills behind Moonbrook. Once you return, we can detonate the explosives. Hopefully with the forge gone, the land can begin to heal.", sourceObjective = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit.", completion = "So you found the forge, and planted the bomb... only one thing remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[92754] = { id = 92754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Need for Shadow Protection", description = "Our clanmates continue to venture further south, to and beyond the cursed Valley of Bones.\n\nDespite your standing with our clan, I do not trust you enough to share the details of their ventures. They would be boring to you anyway, outsider.\n\nWhat matters to you is our need for Greater Shadow Protection Potions, in bulk, to ensure their continued survival. Bring some to me, and I will put in a good word for you.You will be able to choose one of these rewards:", sourceObjective = "Maintain your reputation with the Magram, and bring 3 Greater Shadow Protection Potions to Mirda in the Magram Village in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[92812] = { id = 92812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Economic Warfare" }
quests[92818] = { id = 92818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big, No, MASSIVE Iron Axes", description = "WE NEED MORE WEAPONS.\n\nMORE. WEAPONS.\n\nHOW ELSE IS THE MAGRAM GOING TO SMASH PUNY GELKIS?\n\nI WANT TO SEE WHAT YOU CAN MAKE, OUTSIDER. BRING ME AXES. BIG, NO, MASSIVE ONES.\n\nHURRY UP.You will be able to choose one of these rewards:", sourceObjective = "Maintain your reputation with the Magram, and bring 2 Massive Iron Axes to Grolkar in the Magram Village in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[92819] = { id = 92819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destruction in Deadmines", description = "We are almost finished. Use the detonator, and end this.", sourceObjective = "Use the detonator.", completion = "I don't know what to say, {name}. To think that Stormwind would put their military ambitions over the livelihood of their people...", sourceObjectiveStatus = "unverified-source-field" }
quests[92834] = { id = 92834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenged Tenfold", description = "When the cult began their campaign of violence, the Peacekeepers and Windshapers responded with posturing. I saw this as foolish escalation so I advocated for peaceful dialogue. Yesterday I dispatched my friend Belathaan Brightwish to the Shrine of Akir, hoping to establish that dialogue.\n\nA box just arrived containing Belathaan's tongue, dipped in silver pigment. \n\nIts clear to me now that there is no reasoning with the cult. Kill any cultists you see, and bring me the prayer charms that they carry.", sourceObjective = "Collect 10 Al'Aketh Windstone Charms from Al'Aketh cultists found north of Valanaar at the Gustberry Fields or Shrine of Akir.", progress = "The mark of a leader is the ability to admit when they were wrong. I don't agree with the Windshapers often, but they were right to dismiss the idea of trying to engage peacefully with the Al'Aketh. My attempt to take the high road cost a dear friend his life and is a mistake I will have to live with for the rest of my days.", completion = "The High Order prides ourselves in our pragmatism and logic, and logic dictates that the avoidance of conflict and loss of life is the most prudent option in most situations.\n\n<Elaadrin's eyes begin to glow and crackle with arcane energy.>\n\n...however, the cult mistook our prudence for weakness and they are not nearly ready to pay the cost of that error.", sourceObjectiveStatus = "unverified-source-field" }
quests[92840] = { id = 92840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catching Wind", description = "Fillion was sent to the Overlook Standing Stones with a special device used to measure and study the elemental energy there.\n\nTake this--an Index Esoteria--and use it to extract data from the massive windstone formations that form there. Be on your guard however, as the Windshapers are likely to be jealously guarding this site now.\n\nShould any attempt to obstruct you, well... do what you need to do. I have no more patience for their interference.", sourceObjective = "Take the Index Esoteria to the Overlook Standing Stones in Shen'dar Highlands and use it on the Windstone Formations in the area to gather data.", progress = "It's often difficult for me to establish a distinction between the Windshapers and the Al'Aketh, save that one is more overtly violent than the other. Equally slavish to their misplaced beliefs, they are both equally dangerous if left to their own devices.\n\nThey see our desire to better understand this realm and its magic as a desecration of their traditions. Their small-mindedness is why our mission is so important. If not us, who will have the courage to save Zephras?", completion = "It would not have been my preference to spill Windshaper blood but the blame for this pointless conflict rests solely on their shoulders. We sought to peacefully gather information, and they responded with violence.\n\nUnfortunately, word has spread and the Windshapers are already calling it a 'massacre'. They wouldn't dare to retaliate here in Valanaar, but they will certainly not forget.\n\n{name}, you have been of tremendous aid to the High Order. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[92849] = { id = 92849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scholar", description = "<Judging by what you've just found, it's very likely that Fillion befell some misfortune here. He may still be nearby, and he might be in need of aid. You notice a cave just to the north of your current location. You should continue searching for him there.>", sourceObjective = "Keep searching for Fillion Flamebreeze.", completion = "Th... thank you, stranger. I was walking down the road on my way back to Valanaar when a looming shadow appeared overhead. I turned to look and saw a massive, terrible beast bearing down at me from the sky. I tried to run, but I was hit hard and the world went black.\n\nI think its fair to say that if you hadn't come along, I'd have been dinner for that beast and its young.", sourceObjectiveStatus = "unverified-source-field" }
quests[92850] = { id = 92850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Scholar", description = "I am feeling much better already. I have some skill with the arcane arts and we are but a short distance from Valanaar. I can make it on my own. More important than my safety however is how close to Valanaar these shrieklings have nested and the danger they pose. If you would be so kind, please head back inside and take the head of that beast!\n\nAfter it's done, you'll find me back in Valanaar. I need to report to the Supreme Magister what occurred here and the status of my mission.", sourceObjective = "Slay the Shriekling Matriarch in the Shriekling Den then return its head to Fillion Flamebreeze in Valanaar.", progress = "That fool Fillion...", completion = "Well, I confess that I am intensely relieved that Fillion has returned to us. He never was good at minding his surroundings. Always too busy lost in thought, or with his nose in a book.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[92860] = { id = 92860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of Zephras", description = "The High Order has done our best to avoid direct conflict with the cult, but that is clearly no longer an option. Their hostility has been clearly demonstrated, and now there's rumors of larger-scale cult movements around the island. They are clearly gearing up for something and whatever it is can't be good for the people of Zephras.\n\nReport to Valennia Stormfist and inform her that the High Order offers our full support in Valanaar's efforts against the Al'Aketh, should the need arise.", sourceObjective = "Report to Valennia Stormfist and let her know that High Order is with them in their fight against the Al'Aketh.", completion = "I am sorry to hear about Belathaan. He was actually my cousin and he was a good mage and servant of Zephras. We will avenge him.\n\nYou seem eager to lend aid immediately. Come, let's speak further on the current situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[92871] = { id = 92871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of Zephras", description = "Valennia Stormfist and her peacekeepers have ever been the protectors of Zephras, and we've done our best to lend aid where we can. There's rumors of larger-scale cult movements around the island, and they are clearly gearing up for something.\n\nReport to Valennia and reiterate to her that the Windshapers offer their full support in Valanaar's efforts against the Al'Aketh, should the need arise.", sourceObjective = "Report to Valennia Stormfist and let her know that the Windshapers are with them in their fight against the Al'Aketh.", completion = "You seem eager to lend aid immediately. Come, let's speak further on the current situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[92880] = { id = 92880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Valanaar", description = "I suspect it will take a bit of time for us to mop up what's left of the attackers, but our chances are far better now. Head back to Valanaar and let them know that we are stable here now.\n\nI can't thank you enough for your help. We'd be in much worse shape without you. I asked for reinforcements and it seems that I got a burgeoning hero instead. I'll take that.\n\nMay the four winds bless you, {class}.", sourceObjective = "Bring Yorna's Report to Valennia Stormfist in Valanaar.", completion = "<Valennia looks visibly relieved as you tell her about the status of the eastern watchtower.>\n\nThank the winds.", sourceObjectiveStatus = "unverified-source-field" }
quests[92881] = { id = 92881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Elder's Request", description = "The attack on both the western and eastern watchtowers are not a coincidence. Based on what you told us about what occurred at the western watchtower with that skypriest, our best guess is that the cult is trying to do something to the anchor pylons.\n\nPlease speak with High Elder Shadowsong. He will tell you about a lead that could prove to be promising.", sourceObjective = "Speak with Talaanis Shadowsong in Valanaar.", completion = "I have a small matter that requires just the kind of assistance that an adventurer like yourself can provide.", sourceObjectiveStatus = "unverified-source-field" }
quests[92909] = { id = 92909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Harvesters", description = "Oh no... I'm in for it now!\n\nI heard about the harvesters terrorizing the fields of Westfall, so I traveled all the way from Ironforge to see if I could recalibrate them. But they're far more aggressive than my calculations anticipated, and they chased me into this stable!\n\nIf I had some isosprings and gyrostabilizers from the harvesters, I could build a device to cover my escape. Could you gather the parts for me?", sourceObjective = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers.", progress = "It's a mess out there, {name}! Did you collect the parts I need?", completion = "Thanks a bunch! I'll get to work on an escape plan. In the meantime, take this!", sourceObjectiveStatus = "unverified-source-field" }
quests[92910] = { id = 92910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Harvesters", description = "The part you managed to salvage from the harvester appears mostly intact. Someone interested in harvest golems may want to see it.", sourceObjective = "Bring the Precessive Autocognition Assembly to Ozwin Ironsprocket at Saldean's Farm.", completion = "What's this?", sourceObjectiveStatus = "unverified-source-field" }
quests[92911] = { id = 92911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting the Harvesters", description = "I see... this gives me some insight into what makes those monsters tick. I have an idea how we could override their systems, at least momentarily.\n\nI'll continue tinkering with the assembly you brought me. In the meantime, could you scrounge up some parts for the device?", sourceObjective = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 8 Golem Isosprings, 4 Copper Modulators, and a Crude Scope.", progress = "How's the project coming, Raton?", completion = "Here it is, Raton! Should work great. Go give it a try!\n\n...Me? No, I'll stay here. It's starting to feel like home, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[92947] = { id = 92947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Our Move", description = "Everyone is here, good. I've just sent a few of my best fighters in through the front of the shrine to cause a bit of trouble and serve as a distraction, while I lead the Windshapers and High Order in from the flank.\n\nIf all goes well, we should be able to punch through quickly and take out the High Priestess. As for you, get in there and start cracking skulls. Meet my second, Hyusaa Quickbreeze, near the steps to the shrine after you've caused some trouble.\n\nWinds guide you, {class}.", sourceObjective = "Slay 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers, and 7 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir.", completion = "We fought hard to get this far but it isn't over yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[93036] = { id = 93036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Cult", description = "You may or may not be aware of this, but Sania Silverstream over there is a \"missionary\" for the Al'Aketh. They like to play at being a normal religious order and send non-threatening emissaries around to recruit. We've tolerated Sania so far to avoid direct conflict with the cult, but its obvious the illusion of peace won't last much longer.\n\nYou are new here and unknown to most, so I'd like to see if you can use Sania to get close to the cult and find out what their plans are for the village.", sourceObjective = "Speak with Sania Silverstream in Shen'dar Village.", completion = "Greetings child, my name is Sania Silverstream and I am a junior priestess in the Order of the Al'Aketh. Do you wish to learn more of our sovereign, the Windlord Al'Akir?\n\nThere is always room at the Windlord's table for the righteous and the repentant.", sourceObjectiveStatus = "unverified-source-field" }
quests[93065] = { id = 93065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Battle", description = "The Peacekeepers are mobilizing and we are all gearing up to head out. Make whatever preparations you need to make and meet us at the eastern road leading north out of town. We'll have one final check-in with everyone before we move out.", sourceObjective = "Speak with Valennia Stormfist in the Gustberry Lowlands.", completion = "We are as ready as we'll ever be.", sourceObjectiveStatus = "unverified-source-field" }
quests[93066] = { id = 93066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bristleback Retreat", description = "On the other side of the valley, we have established a small foothold to prepare to march into the forest nearby. Before you head straight there, I want you to deal with a recent Bristleback intrusion along the way. They seem to have arrived right around the same time we did, but managed to secure an artifact from the nearby temple that has kept us at bay.\n\nThis task is simple. Look for the thorns and the pigs. Kill a bunch, indiscriminately. Then report to Hagiak at the camp I mentioned.", sourceObjective = "Maintain your reputation with the Magram, and slay quilboar at Bristleback Retreat. Then report to Hagiak at the Magram Front on the other side of Valley of Bones in Desolace.", sourceObjectiveStatus = "unverified-source-field" }
quests[93072] = { id = 93072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long-Term Solutions", description = "There is a second centaur village out here, to the southwest. That one belongs to the Gelkis. You expect me to send you over just to spill some blood, right? Good. That had best be your first thought, else I would cast doubt on your allegiance to the Magram!\n\nWhat are you waiting for? Go! Kill!", sourceObjective = "Maintain your reputation with the Magram clan and slay 2 Outcast Scouts, 6 Outcast Marauders, and 8 Outcast Necromancers then return to Hagiak at the Magram Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[93089] = { id = 93089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Comes Next", description = "Please extend my thanks to Elaadrin for all that the High Order and your new friends from this \"Kirin Tor\" have done for Zephras Isle. I'm aware of the High Order's plans to leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever arcane solution the High Order finds can truly provide us with the stability we've lacked these past years. If you plan to go with them... well, his mission will be all the stronger for it.\n\nWinds be with you, {name}.", sourceObjective = "Speak with Elaadrin Evengale when you are prepared to leave Zephras Isle.", completion = "It gladdens me to hear that we have High Elder Shadowsong's blessing for our expedition. Now that the cult has been defeated and preparations have been made, I think it's finally time.\n\nAnsirem has worked diligently to help us get stable skycutter transport going between the city of Dalaran and Zephras Isle. We've done as much testing as we can, and the time has come for vanguard to depart.", sourceObjectiveStatus = "unverified-source-field" }
quests[93090] = { id = 93090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Comes Next", description = "Please extend my thanks to Ayessa for all that the Windshapers and your new friends from this \"Earthen Ring\" have done for Zephras Isle. I'm aware of the plan to take the Windshapers shamans and leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever solution the Windshapers find can truly provide us with the stability we've lacked these past years.\n\nWinds be with you, {name}.", sourceObjective = "Speak with Ayessa Dawnsinger when you are prepared to leave Zephras Isle.", completion = "I'm pleased to hear that we have High Elder Shadowsong's blessing for our expedition. Now that the cult has been defeated and preparations have been made, I think it's finally time.\n\nMuln has worked diligently to help us get stable skycutter transport going between Zephras Isle and a place called Mulgore, where the Earthen Ring make their home. We've been doing test voyages and some of our people are already waiting on the other side.", sourceObjectiveStatus = "unverified-source-field" }
quests[93129] = { id = 93129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat of Starvation", description = "Since you seem overly eager to help our clan, I am sure you would be willing to fetch some supplies while you are over in the Outcast Hideaway.\n\nFelling our foes should be enough motivation for a Magram, but I see no reason why we could not profit from the endeavor, too.\n\nWhen we have the exiles dealt with, we can secure this place for the Magram and raise an army to bring the other clans to their knees!", sourceObjective = "Maintain your reputation with the Magram, and bring 6 Stolen Supplies back to Hagiak at the Magram Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[93159] = { id = 93159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strange Hermit", description = "Uh, um... h-hello, I mean to say, hi! Greetings, even! I'm sorry... its um, been so long since I've actually spoken to another person. I'm afraid I'm a bit rusty at this.\n\n<The strange hooded figure shifts uncomfortably before you.>\n\nSo er, um... how is your day going?", sourceObjective = "Speak with the Strange Hermit in the Shadowgale Forest and learn more about him.", progress = "So that's the story...", completion = "...that's about all I have to say about it. I was--um--somewhere else before I was here. Now I'm here and I have my friends, and my things. T-things I built, I mean. That's about all I need. I think that's all I need, anyway.\n\nI have to say though, it is nice to talk to someone who will talk back. The forest spirits try, but they just end up singing at me. That's nice in its own way, but not exactly s-stimulating conversation.", sourceObjectiveStatus = "unverified-source-field" }
quests[93160] = { id = 93160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forest's Bounty", description = "I do appreciate you stopping by to talk with me! I-If you do want to help out, I could use a bit of help gathering up acorns from the forest floor. I've gathered most of the ones close by but there sure are a lot of raptor-bird things in the forest. It's dangerous out there and I'd rather not become a giant bird's lunch!\n\nSo if you want, you could maybe gather them for me? I'll make us something tasty if you do!", sourceObjective = "Gather 8 Shadowgale Acorns in Shadowgale Forest.", progress = "Mmm, I think you are going to like what I can cook up with these acorns!", completion = "Thank you, stranger! You'll find that these are delicious once roasted! \n\nPlease excuse me, it won't take me long to whip this up.", sourceObjectiveStatus = "unverified-source-field" }
quests[93165] = { id = 93165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy Falls on Deaf Ears", description = "The Al'Aketh have visited great tragedy upon our enclave, and blood must be repaid with blood.\n\nI have an offer for you, stranger. Should you find conflict with these accursed cultists, bring me the ears of those you kill. I will reward you for each that you return with in both coin and, in time, access to the Nightclaw's secrets should you prove yourself to be a true friend.", sourceObjective = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands.", progress = "I will not rest until my fangs have gone through the throat of every single cultist on this isle.", completion = "Excellent work. Only good things can happen by eliminating the cult. Hopefully this sends a message that the Nightclaw are not to be trifled with and that our resentments run deep.\n\nI suspect you have your work cut out for yourself, taking on the cult. If you gather more ears bring them here.", sourceObjectiveStatus = "unverified-source-field" }
quests[93172] = { id = 93172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Hollows", description = "Most of the elves on this island seem to think that these woods are haunted, and they aren't wrong.\n\nAt the old ruins to the northeast, a strange type of ghost-like spirits gather. Some nights, you can almost hear them \"singing\". It's not like any song I've heard before, but its definitely a song and its... just so sad.\n\nI'm not sure why, but I think something terrible happened there at some point, and the spirits are trapped there somehow. If you are feeling brave, maybe you can help set them free?", sourceObjective = "Destroy 10 Wind Hollows in Shadowgale Forest.", progress = "We can only hope that those poor spirits are able to find peace after being freed from this place.", completion = "Thank you, stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[93176] = { id = 93176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Little Friends", description = "Admiring my little menagerie, are you? They are my un-life's work. I've spent countless hours studying them: their anatomy, their diets, even their social rituals.\n\nDo you wish to join me in the hobby? Here, take this package. The notes and materials contained within should get you started. If you lose it, you'll have to purchase another one from me for a small fee.", sourceObjective = "Use the items contained in the Entomology Starter Kit to find and catch an Arbor Tarantula, Hay Weevil Specimen, and a Flesh Picker.", sourceObjectiveStatus = "unverified-source-field" }
quests[93224] = { id = 93224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Centaur Totems", description = "It likely comes as no surprise to you that both of the centaur clans are hesitant to accept aid from anyone outside of their clan. This is especially true for folks like you and me - you know, non-centaurs.\n\nOne thing we all have in common is an understanding that money is power, and we have learned that the local centaur barter with carved wood. If you bring me a few samples of their designs, I can put in a rush order for similar etchings. Perhaps we can buy ourselves an advantage.", sourceObjective = "Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel's Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[93225] = { id = 93225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Centaur Totems", description = "I have noticed that centaur from different clans sometimes gather away from settlements and engage in trade. I have observed this across numerous nights and seemingly with every clan; most importantly I have seen the currency they use: carved totems.\n\nI believe we can turn the tides in our favor with either the Gelkis or the Magram if we deliver a heavy bundle of totems right to them. I have already begun carving some, but I doubt they will be easily fooled without a few authentic ones.", sourceObjective = "Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[93226] = { id = 93226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Friendship: Magram", description = "Siding with the Magram would be my choice. There is no question that they are the dominant clan in the present day, regardless of their previous struggles. I have heard reports that they are brutally hostile against the Gelkis.\n\nI sympathize with both warring clans and especially the Gelkis, but this is their war; not ours. We ought to side with the faction that poses the least risk to our cause. I believe that to be the Magram.\n\nBring this to their quartermaster in Magram Village to the southeast.", sourceObjective = "Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[93227] = { id = 93227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Friendship: Gelkis", description = "At first glance, I would wager that the Gelkis are struggling. Their numbers are far fewer than the Magram, and I rarely hear of them stomping around from our scouts.\n\nNonetheless, they are one of the dominant clans in the Desolace and survive to this day. They must be doing something right.\n\nIf you want to make peace with the Gelkis, take this tote of totems with you to Gelkis Village far to the southwest. Primitive as they may be, they are likely to have a treasurer of some kind.", sourceObjective = "Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[93317] = { id = 93317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Season", description = "Are you familiar with Windsong Crawlers? You see, these crabs are native only to Windsong Lake here on Zephras, and they are only able to be harvested a few weeks of the year.\n\nWith all of the cult activity of late, I've not been able to get out to the lake to harvest them, and our window is rapidly closing. I'd be appreciative if you could go and gather some for me. They can generally be found along the shorelines around the lake and in rivers.\n\nDo be careful though, they are meaner than they look!", sourceObjective = "Collect 6 pieces of Windsong Crawler Meat.", progress = "Windsong Crawler meat is common enough here but it was something of a delicacy on the islands of Anvilas and Siroccas. Was a time, back when the skystreams were open that the locals would mob me for the stuff when I'd make the trip to Shen'dramar or New Eldre'naar.\n\nNot been able to visit those places in... well... a long time.", completion = "Winds bless me this meat looks fantastic! \n\nThank you so much, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[93318] = { id = 93318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Vulgara the Insatiable", description = "By order of Constable Aonda of the Peacekeepers, a bounty is hereby placed upon the scourge of the highlands, Vulgara the Insatiable. Last spotted on a hilltop rise just southwest of Shen'dar Village, the winged vuldren terror is highly dangerous and should be approached with caution.\n\nDeliver the beast's head to Danarii Bellowveil to receive your reward.", sourceObjective = "Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil.", progress = "I'll need the creature's head as proof of the deed.", completion = "If we didn't have enough on our plates between the cult and the highlands bandits, we don't need a giant vuldren terrorizing our citizens as well. You've done a great thing here today. As promised, here is your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[93319] = { id = 93319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Windstones", description = "We are relying on windstones more and more for day to day living here on Zephras so we try and maintain a cache of them in reserve for emergencies. Lately I've noticed some go missing from our stores.\n\nWe've found windstones on bandits we've captured recently, and I suspect they are behind our shortages.\n\nIf you find yourself near the bandit cave to the north, mind knocking a few heads together and reclaiming some of our pilfered windstones for me?", sourceObjective = "Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands.", progress = "These sneakthieves have likely been breaking into our supplies for months. I tried to convince Aonda to put a raid together to clear out that bandit cave for good, but she didn't want to pull the few peacekeepers we have away from the village. \n\nWith the cultists at Falaath Village to the south growing in numbers, I suppose I can't fault her for that.", completion = "Thanks {class}. This should help us get by for now. If we can't get the supply routes squared away soon though, a few stolen windstones will be the least of our worries.", sourceObjectiveStatus = "unverified-source-field" }
quests[93320] = { id = 93320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower Defense", description = "I've just received word that the cult is attacking the pylon watchtower just outside of town! I've sent the few extra peacekeepers we have here to try and break through the enemy back line to relieve the defenders, but any additional help could mean the difference between our people there living or dying.\n\nPlease leave immediately for the east watchtower and provide whatever aid you can.\n\nMy lieutenant Yorana Windyreed led the relief force. If she still lives she can tell you how best to help.", sourceObjective = "Report to Yorana Windyreed at the eastern watchtower in the Gustberry Lowlands.", completion = "We are holding them off for now, but they have greater numbers and our fighters are starting to get tired. We need to do something to break the stalemate, and do it fast.", sourceObjectiveStatus = "unverified-source-field" }
quests[93429] = { id = 93429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of My Blood", description = "Although they are our kin, the Lost Ones of Fallow Sanctuary have become beings of pure violence and hatred.\n\nThere can be no redemption or salvation for them. They are doomed to wander this swamp as mindless, hateful creatures for all their lives.\n\nTheir suffering must end. Someone must put them out of their misery. A grisly task, I know, but would you do it to protect those of us who remain?", sourceObjective = "Slay 10 Lost Ones in the Fallow Sanctuary.", sourceObjectiveStatus = "unverified-source-field" }
quests[93430] = { id = 93430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Bait Back", description = "Now they've really done it! As if those wretches weren't already enough to deal with, one of them has stolen my lucky lure!\n\nI was just out fishing this morning, when one came up out of the muck, cut my line, and ran off with it. The thief is almost certainly one of the Lost Ones' own fishermen, hoping to use the lure themselves.\n\nWell, our supply of fish depends on that lure, so I need it back. The Lost Ones fish along the banks east of here. Find that thief, {race}!", sourceObjective = "Find the Lost One Fisherman who stole Pelluk's lure, and take it back.", sourceObjectiveStatus = "unverified-source-field" }
quests[93459] = { id = 93459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Al'Aketh Ears", description = "The Al'Aketh cult normally gives this forest a wide berth, fearing the rumors that it is haunted... rumors we are happy to maintain. The Druids of my order wish only to live quiet, peaceful lives here in Shadowgale and they threaten that. \n\nMany among us are afraid.\n\nI come with an offer. Fight the cultists for us, and bring us the ears of those you kill. We will reward you for each that you return with in both coin and, in time, access to our secrets should you prove yourself to be a true friend.", sourceObjective = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands and return them to Vayn Moonclaw in Shadowgale Forest.", progress = "<Vayn nods at you.>", completion = "As promised, here is your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[93461] = { id = 93461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Shen'dar Village", description = "You've got that \"High Order\" look to you. Those with Highborne ancestry always seem to have a slight twinkle in their eyes that gives it away. Before I properly put you to work around here, you should check in with our resident High Order elder Rathiril Sunlance. You can find him here in the main lodge, just around the corner from me.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them.", sourceObjective = "Speak with Rathiril Sunlance and Coriella Calmbreeze in Shen'dar Village.", completion = "Checked in with Rathiril then? Great. Lots of tension between the High Order and the Windshapers these days, but they keep things civil here in Shen'dar. Well, at least in the village anyway. What happens out in the wilds stays in the wilds.\n\nNow that that's done, you look like someone who might be looking for something to do with their hands. I've got a few things that need doing, if you are game for a bit of work?", sourceObjectiveStatus = "unverified-source-field" }
quests[93464] = { id = 93464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Visiting Mage", description = "Allow me to admit something, {name}. While draenethyst is sacred to us, and keeps us sane, none here fully understand it.\n\nI recall a mage who once came to the Harborage, from Desolace. A human by the name of Azore. He feared the power of the draenethyst; said it shouldn't fall into the wrong hands. \n\nAt the time, we drove him away to protect what was ours. Lately, however, I find myself wondering what exactly he knew.\n\nI ask that you find this mage, {race}. His knowledge could be of immense value to us.", sourceObjective = "Find the mage in Desolace who knows about the power of draenethyst.", sourceObjectiveStatus = "unverified-source-field" }
quests[93465] = { id = 93465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notes on Draenethyst", description = "I suppose it would be more accurate to say I know someone who knows a thing or two about draenethyst.\n\nYou see, the warlocks of the Burning Blade have been studying it. It is a substance from beyond the dark portal, so it follows that those involved with darker arts might wish to harness it to their own ends. We cannot allow this, obviously.\n\nThe specific warlock you seek is named Gimashi. She can be found atop her tower, which is in a ravine to the southeast. Her notes will have the answers you seek.", sourceObjective = "Take Gimashi's notes on Draenethyst, and bring them back to Azore Aldamort.", sourceObjectiveStatus = "unverified-source-field" }
quests[93552] = { id = 93552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harvesting Windstones", description = "Windstones are a critical resource on Zephras Isle as they contain the raw, concentrated energy of the winds themselves. The wind elementals who used to live here on zephras with us vanished several centuries ago, and since then, the magic that sustains this island is slowly fading. Not without limitations, the Windstones are still a reliable energy source, and are incredibly valuable to us.\n\nYou'll find raw Windstones scattered around the grove, think you can help me harvest them?", sourceObjective = "Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove.", progress = "Hello there, {class}.", completion = "Thank you very much for these. As elves we all have a deep connection to magic and these windstones are becoming more and more precious as the magic imbued into this island by the great anchor pylons continues to fade. \n\nwindstones aren't the only beneficial thing you can harvest from the land. Please, take one of these manuals.", sourceObjectiveStatus = "unverified-source-field" }
quests[93585] = { id = 93585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Light of Mine", description = "Oh thank goodness, someone civilized!\n\nI came here on behalf of the Church of the Holy Light to make contact with the draenei of the Harborage. The Alliance has no foothold here, you see, and a bit of diplomacy with the locals may help us in that regard. The Light welcomes all into its fold, after all!\n\nHowever, the road past this bridge is crawling with the draenei's more savage kin. If I am to make it to the Harborage safely, I will need protection. Would you aid me, {class}?", sourceObjective = "Escort Father Tuttle to The Harborage.", sourceObjectiveStatus = "unverified-source-field" }
quests[93663] = { id = 93663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Transit", description = "The draenei of the Harborage are skilled fishermen, and willing to trawl more dangerous waters than I. We occasionally trade. They give us some of their catch, and I offer some of our extra supplies.\n\nI'd sent a goblin courier to deliver my latest shipment, but he never returned. A crocolisk likely made a meal of him.\n\nMore importantly, my business reputation is at stake. That shipment must be found, and delivered to the harborage. Please, find it if you can. Check near the waters along the road.", sourceObjective = "Find the missing courier, and ensure Dar's shipment is delivered to the Harborage.", sourceObjectiveStatus = "unverified-source-field" }
quests[93680] = { id = 93680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Key to the City", description = "The Alliance had an army of mages known as the Kirin Tor. While they were powerful, the demonic Burning Legion proved to be even more so. In one fell swoop, the arch demon Archimonde flattened their city like it was a child's plaything. Those who remained were reduced to merely dispossessed vagabonds.\n\nThat is, until they rebuilt Dalaran. And on the Dark Lady's very doorstep, no less!\n\nWhile in their camps, search for something that can get us into the city unnoticed. I must know more.", sourceObjective = "Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill.", sourceObjectiveStatus = "unverified-source-field" }
quests[93735] = { id = 93735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Construct", description = "Historically, the Windshapers have seen to the tending of the magical instruments and devices that were gifted to us by the spirits of the wind. This includes the myriad of magical constructs around the island. Since the spirits left us, only a scant few of these are still functional.\n\nOne of the few remaining working constructs in Valanaar has become damaged. One of our artisans was dispatched to help, but he may be in need of aid. Travel to the west end of the city and offer any assistance you can.", sourceObjective = "Find Riaani Nightwind on the west side of Valanaar.", completion = "<Riaani's face is buried under the heaving armor plates of the construct, attempting to work on the mechanisms underneath. He does not notice your presence at all.>\n\nStorms curse where is the core?! Who thought it would be a good idea to remove the Gyrozephyr as well? It's a miracle this construct's winds haven't dissipated entirely by now!", sourceObjectiveStatus = "unverified-source-field" }
quests[93736] = { id = 93736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Spirits", description = "The paramount concern of the Windshapers is to better understand why the spirits left us, and what we may be able to do to bring them back. One curious fixture of Shadowgale Forest to the north is the presence of a curious form of wind sprite that some call \"hollows\". We know little of them and why they are there, but we do know that they first started to appear after the spirits of the wind left us.\n\nI need you to go there and disperse them. Gather the remains and bring them back here.", sourceObjective = "Gather 10 Wind Hollow Essences from Wind Hollows in the Shadowgale Forest.", progress = "Shadowgale Forest is a dangerous place. Some even say its haunted. I'm quite sure that I don't believe that, but I do know that its not for the faint hearted, or the unprepared.", completion = "Handling these essences fills me with a sense of... deep disquiet. I can almost feel a malevolent, regretful aura emanating from them. It's enough to make me faint.\n\n<Endaria shudders slightly.>\n\nI do not look forward to studying these further.", sourceObjectiveStatus = "unverified-source-field" }
quests[93737] = { id = 93737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Construct", description = "Oh, hello. Ayessa sent you to assist me? Very well then. \n\nNot sure what an obvious novice like yourself can do, but if you give me a moment to pull my head out of this construct's innards I might have a few ideas of things you can do to help.", sourceObjective = "Speak with Rianni Nightwind and list to what he has to say.", progress = "I can't imagine why anyone would want to steal these components from this construct. Other than the gyrozephyr these components have almost no practical application. Even the gyro would be nigh-useless outside of its intended purpose.", completion = "Thank you for scavenging these materials. I imagine that some of this wasn't terribly easy to get. \n\nWith these parts I can get the construct up and running again. From there we can just hope that its memory is intact and it can tell us who took its components.", sourceObjectiveStatus = "unverified-source-field" }
quests[93738] = { id = 93738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Construct", description = "Brightwish, eh? So the High Order wanted to remove these components for some reason. But why though?\n\nThe High Order has always been meddlesome, constantly wanting to experiment with the wind spirits' magic. They are too bold by a mile, and we've strictly forbade them from meddling with knowledge under Windshaper purview, but lately they've been testing our patience. \n\nI think you should report what you've learned back to Ayessa Dawnsinger. She can instruct you further on what to do.", sourceObjective = "Report back to Ayessa Dawnsinger in Valanaar.", completion = "Very interesting, so it was the High Order that was responsible for the construct breaking down?\n\nI know Belathaan. He's Valennia Stormfist's cousin and his mother was actually a Windshaper. It's disappointing that he was involved in this.\n\nI need to reflect on this for a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[93739] = { id = 93739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploring the Horde", description = "Azeroth is a large world, and the territory of the Horde is vast. The Undercity, Orgrimmar, and Thunder Bluff all have very unique people and culture.\n\nIf you are to be a guest of the horde here on Azeroth, it would do you good to visit each of our capital cities in turn. Speak with my advisor Nazgrel for directions.", sourceObjective = "Speak with Nazgrel in Grommash Hold to receive further instructions. Use the instructions received to locate and speak with Vol'jin, Cairne Bloodhoof, and Lady Sylvanas Windrunner.", completion = "So you have returned. I hope that you learned much in your journey.\n\nIt is my understanding that your people are still establishing themselves in Mulgore. While you wait for them, I'd encourage you to explore the territory around Orgrimmar. The Barrens in particular is always in need of eager adventurers like yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[93740] = { id = 93740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood for Blood", description = "A number of our Windshaper novices were found dead in the Highlands this morning. We can't be certain but there is a strong chance that the Al'Aketh are responsible. Windshapers trade blood for blood, every time.\n\nHead north and kill any Al'Aketh you encounter. Bring me their windstone prayer charms as proof of the deed. We do not forgive and we do not forget.", sourceObjective = "Collect 10 Al'Aketh Windstone Charms from the corpses of Al'Aketh cultists in the Gustberry Lowlands.", progress = "The Al'Aketh have engaged in their bloody zealotry for far too long. This is only the start of the reckoning they face.", completion = "<Ayessa looks shaken and distant as you hand her the windstone charms.>\n\nDon't mind me, {name}. Today has merely been... a trying day. Thank you for your service to the windshapers thus far.", sourceObjectiveStatus = "unverified-source-field" }
quests[93746] = { id = 93746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Firm Response", description = "The High Order has been warned of the consequences of meddling with the Windshaper's affairs. I think we need to make an example out of Belathaan and send him back to the High Order with a few bruises and a healthy respect for the boundaries we set.\n\nBelathaan was seen leaving town, traveling north towards the Shrine of Akir. I don't know why he was going there, but confronting him alone on the road is the safest option. Find him, and put a bit of fear into his heart.", sourceObjective = "Confront Belthaan Brightwish along the road to the Shrine of Akir.", completion = "Wait--what?! Belathaan... is dead? \n\n<Ayessa listens as you give your account of what occurred.> \n\nThe High Order was meeting with the Al'Aketh to discuss peace? There is no peace with the cult, they are murderous zealots. What was Elaadrin thinking sending Belathaan to treat with them alone?\n\nPay this no mind, {name}. You are not at fault for this. The arrogance of the High Order is to blame, yet again. You were merely in the right place at the wrong time.", sourceObjectiveStatus = "unverified-source-field" }
quests[93791] = { id = 93791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Belann", description = "{name}, it is clear your skill with magic is growing and I believe it is time for you to partake in one of the High Order's oldest traditions for young and aspiring mages. It is time for you to craft a spell focus of your own.\n\nSeek out Belann Windwood in Valanaar. He has been crafting staves and wands for the High Order for over a century, so you will be in good hands.", sourceObjective = "Speak with Belann Windwood in Valanaar.", completion = "Ah, you must be {name}? It is heartening to see young mages eager to learn our ways and history. Come, I will explain the next steps to crafting your spell focus.", sourceObjectiveStatus = "unverified-source-field" }
quests[93797] = { id = 93797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boughs in the Wind", description = "It is a time-honored tradition for young mages to create their own spell focus when they have shown a certain degree of magical proficiency. This is typically done by gathering a fallen branch from our oldest trees, as they have some lingering traces of elemental wind.\n\nI have found the most ideal ones to be near the wind shrine, just south of Falaath Village. Go and bring me back a large branch and I will teach you about the traditions as we create your spell focus.", sourceObjective = "Bring a Wind-Infused Bough to Belann Windwood in Valanaar.", progress = "Every year that passes in Zephras sees fewer and fewer of those who are gifted with a talent for magic. \n\nI am glad to see young mages such as yourself participate in our oldest traditions to help keep our history and culture alive and well.", completion = "Thank you, {name}. I can indeed feel the elemental energies in this bough waiting to be harnessed by those that have the gift to do so. This will make an excellent spell focus.\n\nDid this branch sing to you, perhaps? It has often been the case that the branch picks the {class}, and not the other way around.", sourceObjectiveStatus = "unverified-source-field" }
quests[93835] = { id = 93835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confront Lorthuna", description = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Elaadrin and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, {class}.", sourceObjective = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with High Priestess Lorthuna.", completion = "I sent a few of our remaining mages to ensure that Valennia and her forces were able to escape as well. She should be resting at High Elder Shadowsong's residence now.\n\nAnsirem had to return to Azeroth, but he and I discussed the next steps for the High Order before he departed. We survived the day, but Zephras is dangerously vulnerable now and we must make plans for what is to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[93836] = { id = 93836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Zephras", description = "Muln has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir. Now that the wards that have hidden Zephras from his view are down, we are utterly defenseless. If he chooses to attack us, we stand no chance against him here in his own domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it.", sourceObjective = "Speak with Talaanis Shadowsong in Valanaar.", completion = "<Talaanis Shadowsong listens intently as you tell him of what transpired above the Shrine of Akir, and of Ayessa's plan to leave Zephras Isle.>\n\nI need to reflect on this further, but looking at the upside, we have rid ourselves of Lorthuna and deprived the cult of their leader. Our home has not been invaded yet and on the timeline of elemental gods, it could be years... decades even, before Al'Akir deigns to turn his attention to us.\n\nThere is much to fear now, but much to celebrate as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[93862] = { id = 93862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crate Return" }
quests[93926] = { id = 93926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Watch", description = "Whatever reason the cult has for attacking the tower, it's not worth losing our people over.\n\nI'd like for you to head to the southwest and check in on that watchtower for us. Find the peacekeepers there and tell them to head back to the village. Holding that tower is not worth the lives it would cost and I'd rather concentrate the defenders we do have here to protect our citizens.\n\nPeacekeeper Vaaniel is in charge, let him know to head back here as quickly as possible. Hurry!", sourceObjective = "Find Peacekeeper Vaaniel at the western watchtower.", completion = "<The body here is somewhat fresh, clearly only recently having been killed. Judging by the burns and scorch marks on this peacekeeper's skin, its clear that they were killed by the cult's storm-wielding spellcasters.>", sourceObjectiveStatus = "unverified-source-field" }
quests[93927] = { id = 93927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Last Request", description = "<As you inspect the body of the dead peacekeeper, a bloody note falls free of his hands. Picking it up and reading it may give you a clue as to how to proceed from here.>", sourceObjective = "Collect the note you found near the dead peacekeeper and read it to determine your next steps.", progress = "What news from the western watch?", completion = "So they are all dead, then. Storms curse on these cult bastards!\n\nWhile you managed to take out the priest and stop the cultists at the tower, I confess that I'm now doubly concerned about whatever it was you said that they were doing to the pylon. The fact that there was such a massive cache of windstones there with them tells me that they needed enormous energy for it.\n\nI have to wonder, what's the end goal here? Violating the pylon, attacking the village? To what end?", sourceObjectiveStatus = "unverified-source-field" }
quests[93928] = { id = 93928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Mice and Milk", description = "I need a cookie, see? \n\nNyeah!", sourceObjective = "Get the mouse a cookie.", completion = "(PH) Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[93948] = { id = 93948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Signet", description = "Since you are going to Valanaar anyway, please deliver the signet ring you recovered from the tower to Talaanis Shadowsong in Valanaar. \n\nHe will want this back, and more importantly, he will want to learn the fate of his nephew. Talaanis is the High Elder of Zephras Isle and more importantly, he is a good man who is well loved by the people, despite our current hardships. It pains me to think of how he will react to this news. Please express my condolences for his loss.", sourceObjective = "Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar.", progress = "What is that you have for me? Oh... oh no.", completion = "I... am very sorry to hear that my nephew is dead. I thank you kindly for recovering this, and bringing it to me.\n\nIt's not common that such capable young shen'dorei come down from the highlands. If you need work, please speak with Valennia Stormfist, the captain of the peacekeepers here in Valanaar. These days we need all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[93949] = { id = 93949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bugged", description = "We've been bugged.\n\nIt's skyhopper season in the lowlands, which means the pests are everywhere. One of the High Order mages reported that one of the insects that they killed had an enchantment of some kind placed upon it. When we inspected it closely it seems to be some sort of listening spell.\n\nWe suspect that the cult is using these enchanted insects as spies. Go and exterminate them for us. You won't be able to tell which are enchanted by looking at them, so you'll just have to kill them all.", sourceObjective = "Kill Skyhoppers in Valanaar until you've eliminated 8 Enchanted Skyhoppers.", completion = "I'm sure there are more of these critters around Valanaar, but every enchanted skyhopper we stomp out makes the city just a tiny bit safer.", sourceObjectiveStatus = "unverified-source-field" }
quests[93951] = { id = 93951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Beauty", description = "The Hippogryph that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and more importantly, silky soft.\n\nIf you are heading that way, try and gather as many of the fallen feathers as you can from in and around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests.", sourceObjective = "Collect 8 Hippogryph Down feathers in the Shen'dar Highlands.", progress = "What beautiful things did you bring me?", completion = "It might seem a bit of a vain triviality, gathering feathers for our hair. However, even in times like these, one needs to embrace the small joys as much as possible. \n\nIf one thing I create brings someone joy, then I will consider that to be a good day. Thank you for bringing me these and helping me bring some joy to Zephras.", sourceObjectiveStatus = "unverified-source-field" }
quests[93958] = { id = 93958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inner Sanctum", description = "Valennia's forces just breached the inner sanctum. The fighting was thick in there at first, but it's grown... unsettlingly quiet. Go in there and do your best to link up with Valennia and her forces... if any of them are left.\n\nI'll stay here and watch your back.", sourceObjective = "Speak with Valennia Stormfist inside the inner sanctum at the Shrine of Akir.", completion = "<Valennia looks gravely wounded.>", sourceObjectiveStatus = "unverified-source-field" }
quests[93963] = { id = 93963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploring the Alliance", description = "Stormwind, Ironforge, and Darnassus all have unique peoples and cultures. As a guest of the Alliance here on Azeroth, you should take some time to visit each of our capital cities in turn. \n\nSpeak with Randal Emerson in the southern antechamber for directions to get you started.", sourceObjective = "Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind.", completion = "Ah, you are back.\n\nI hope your adventures have given you a sense of the scale and wonder of our world. I know it must seem overwhelming to you, but if you are to help your people, you must be prepared for whatever may come your way while you are on Azeroth.\n\nWhile you wait for your order to establish itself in Dalaran, I suggest you turn your attention to the lands around Stormwind. Westfall in particular can always use more strong adventurers to lend them aid, if you are willing.", sourceObjectiveStatus = "unverified-source-field" }
quests[94003] = { id = 94003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skybreaker Bulwark", description = "I am all that remains of the line of Skybreakers here on Zephras Isle. The rest were murdered by the Al'Aketh.\n\nThe only thing that outweighs my sorrow is my shame. My family's ancestral shield--the Skybreaker Bulwark--is now in the hands of a cultist named Zaal Stormshield. Family lore holds no harm may befall a worthy wielder of this shield.\n\nZaal is not worthy, of that I am sure. Find this man at the Shrine of Akir and reclaim my shield from him. Do this and I will teach you the Skybreaker Defense.", sourceObjective = "Reclaim the Skybreaker Bulwark from Zaal Stormshield at the Shrine of Akir.", progress = "<Seena nods curtly at you.>", completion = "You have done what I could not and restored my family honor. For this, I will bestow a gift that few on Zephras are worthy to receive. I will teach out the secrets of the Skybreaker Defense.\n\nAlso, you will need a shield to put what I have to teach you into practice. Please, take this one. I have little use for it now that the Skybreaker Bulwark has been returned to me.\n\nBanu'Adoraah, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[94004] = { id = 94004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Elixir of Ogre's Strength", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Wut?", completion = "You brought da elixir!!\n\nT'anks, {race}. You come all this way to help Sos'mol. No ogre ever done that before.\n\nSos'mol will remember this. Pay you back someday. Me promise.", sourceObjectiveStatus = "unverified-source-field" }
quests[94006] = { id = 94006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Ursera Spirit", description = "Greetings, {name}. You have progressed in your druidic studies far enough that I think it is time for you to meet one of the great spirits that reside here on Zephras. Urs'endris is a wise and noble spirit, who has taught druids how to take on the ursera shape for generations. Unfortunately his domain has begun to wither and fall into the sky like many other areas of Zephras.\n\nTo find him, travel northeast near the waterfall in the shadow of the Shrine of Akir. He should be able to instruct you further.", sourceObjective = "Speak with Urs'endris near the falls northeast of Valanaar.", completion = "So, you wish to embrace the way of the claw, child? Very well. Let us speak.", sourceObjectiveStatus = "unverified-source-field" }
quests[94007] = { id = 94007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Now that you've gained a level of comfort in the wilds of the highlands, I believe it is time for you to seek your very own animal companion.\n\nGo to the port of Valanaar to the southeast, and speak with Quel'ana Quickgale there. He will instruct you in the art of beast taming.", sourceObjective = "Report to Quel'ana Quickgale in Valanaar.", completion = "I am most glad that you came. Come, let us begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[94013] = { id = 94013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You've returned triumphant from taming two beasts, it's time now for your last trial. The winds of Zephras whisper of greater challenges ahead. \n\nTake this Taming Rod and journey to the Gustberry Lowlands. There, tame a Vuldren Alpha and prove your mastery. \n\nComplete this lesson and you'll be ready to learn the deeper ways of the hunter.", sourceObjective = "Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner. Now that you know the basics, I can teach you how to forge a lasting bond with an animal companion.\n\nGo with this knowledge and thrive. Be the {class} that Zephras Isle needs you to be.", sourceObjectiveStatus = "unverified-source-field" }
quests[94050] = { id = 94050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than my sister, Quel'dora. She will give you the ability to train your new pet. \n\nGo with the winds, young {class}.", sourceObjective = "Speak to Quel'dora Quickgale in Valanaar.", completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date.", sourceObjectiveStatus = "unverified-source-field" }
quests[94212] = { id = 94212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Elixir of Wisdom", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Come, warm yourself by the fire.", completion = "I will admit, I expected the treacherous winds of the highlands to tear that letter to shreds. I had not imagined that someone would see my humble request, let alone deliver it straight to me.\n\nYour efforts are kind and admirable, {race}. I will use this to aid my meditation.\n\nFeel free to stay and share a tale or two of your travels. I enjoy the company.", sourceObjectiveStatus = "unverified-source-field" }
quests[94213] = { id = 94213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Lesser Mana Potion", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Good day, {race}. I appreciate the company but my attention is elsewhere. If we do not have business, please be on your way.", completion = "Ah, is this the potion I requested?\n\n<The elven woman respectfully takes the vial from you.>\n\nYour arrival is timely, and generosity deeply appreciated. I accept this, and offer you a small token of my gratitude.\n\nThank you, may we meet again.", sourceObjectiveStatus = "unverified-source-field" }
quests[94214] = { id = 94214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Shadow Protection Potion", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94215] = { id = 94215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Free Action Potion", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<You approach a thrashing creature clearly trapped in spider silk, exactly where the writ marked on the map.>", completion = "<You waste little time offering the wiggling mass the Free Action Potion that was requested. It seems either unaware of your presence, or unable to claim the item.\n\nA handful of coins are scattered just beside the cocoon. You may decide to leave the potion there, and take the coins for yourself. Nature will surely sort itself out, in that case.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94216] = { id = 94216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Elixir of Lesser Agility", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Are you here about...\n\n<Ziz looks around his tiny hut suspiciously, and lowers his voice.>\n\nThe elixir?", completion = "<Ziz continues to talk in a hushed tone.>\n\nI'm not about to give you the whole spiel about how I got into this position, but here's some advice for you.\n\nSometimes, all you gotta do to impress your new boss is take credit for someone else's work. So you're going to hand over the elixir, and I am gonna talk about how much blood, sweat, and tears I poured into making it.\n\nIt's a new gig, okay? I need to make a good first impression!", sourceObjectiveStatus = "unverified-source-field" }
quests[94217] = { id = 94217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Lesser Troll's Blood Elixir", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, you be bringin' me my elixir?", completion = "Exactly what Short John Mithril ordered!\n\nHere's ye' coin. I'd keep it clutched to your chest as ye' scuttle out of here, the arena combatants thirst for riches as much as they thirst for blood!", sourceObjectiveStatus = "unverified-source-field" }
quests[94218] = { id = 94218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Elixir of Defense", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94219] = { id = 94219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Draught of Water Breathing", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94220] = { id = 94220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Pearl-Handled Dagger", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "It is unwise to sneak up on me, {race}. Speak quickly, and speak quietly.", completion = "Oh, you are delivering my dagger? Hah, I suppose my threat rang quite hollow then, hm?\n\nI must stay on high alert given my duties here, and especially with oth-- ahem, the foul Syndicate roaming about elsewhere here.\n\nWould you be so kind as to part with the blade, now? I must get back to my task.", sourceObjectiveStatus = "unverified-source-field" }
quests[94221] = { id = 94221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Golden Rod", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The dwarf seems to be in a deep state of meditation, though your approach interrupted his focus. Fortunately, a smile greets you.>", completion = "Ah, the Golden Rod I requested. I never expected it to arrive. I was considering going back to Ironforge to purchase one off the auction house. You saved me a trip, something these old feet greatly thank you for.\n\nI do not yet know how I can use this to commune with the Binding Stones, let alone if I even can, but I suspect this brings me one step closer.\n\nIn the worst case, well, I am happy to have a new cane.", sourceObjectiveStatus = "unverified-source-field" }
quests[94222] = { id = 94222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Iridescent Hammer", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94223] = { id = 94223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Silver Skeleton Key", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<After following the instructions on the writ, you find yourself deep in a crypt surrounded by undead. There is a note on a nearby trunk.>\n\nWhomever first reads this will be the first to learn of my death. I am a mere caretaker of the Raven Hill Cemetery, whose presence is largely forgotten by even his employers at Darkshire. I have no heir with which to bestow my vast wealth unto. I have since stashed them away, in this box, for who or whatever manages to open it.", completion = "<With the undead hordes endlessly gathering nearby and no sign of others, you choose to make use of your Silver Skeleton Key to effortlessly open the chest.\n\nDespite the claims of impressive riches, the trunk is nearly empty. At the very least there is enough present to cover some of the cost of this ordeal.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94224] = { id = 94224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Heavy Bronze Mace", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Shh. Keep your voice down. I'm not ready for a fight, yet.", completion = "Whoa. You came well prepared! Hope that mace is for me, unless you plan to do ALL of the fighting.", sourceObjectiveStatus = "unverified-source-field" }
quests[94225] = { id = 94225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Rough Bronze Leggings", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "What's up?", completion = "These are the leggings I ordered, huh? \"Three to five business days,\" they said. More like three to five business MONTHS!\n\nI submitted this when I was working for the Venture Co out there, and let me just say, that partnership is well over with, so we can consider this order expired.\n\nWhy aren't you leaving yet? Ugh, fine! Here's your payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[94226] = { id = 94226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Green Iron Gauntlets", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94227] = { id = 94227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Big Bronze Knife", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The chicken... clears its throat?>\n\nCluck, cluck.", completion = "Cluck? CLUCK CLUCK! BWOK!\n\n<The chicken glares menacingly toward Magus Tirth from afar, newly acquired blade in beak.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94228] = { id = 94228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Green Iron Boots", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Please tell me you're the one with the boots...", completion = "At last! I've been stomping around the wetlands with soggy feet for days!\n\nHopefully these aren't prone to rusting either. I trust you know what you're doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[94229] = { id = 94229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Ornate Spyglass", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Whoa! I almost didn't see you there. I might have seen you coming sooner if a damned engineer would at last deliver my order.", completion = "Oh. Oh! You're the engineer? I suppose at the very least you are the delivery boy in any case.\n\nPlease hand over the spyglass. I have little time and many things to inspect.", sourceObjectiveStatus = "unverified-source-field" }
quests[94230] = { id = 94230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Explosive Sheep", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94231] = { id = 94231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Moonsight Rifle", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey, HEY, man, haven't you heard of a little thing called \"subtlety\"? Spell it out with me, S-U-B...LETY. You're going to blow my cover!", completion = "Ohoho, I take it back. Look at this beautiful boomstick. I bet it'll knock a satyr's head clean off.\n\nThanks pal, now step aside or you're going to get caught in the crossfire.", sourceObjectiveStatus = "unverified-source-field" }
quests[94232] = { id = 94232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Minor Recombobulator", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94233] = { id = 94233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Practice Lock", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "I watched this whole place get burned to the ground and that keep toppled over. It was glorious.\n\nNever expected a group of bandits try to use this place as a base of operations.", completion = "Ahh, my practice lock has arrived.\n\nThe Syndicate here have been plotting to turn this place into a prison like it once was. I already know that at least one orc is currently being held here. Maybe more. I don't intend to be another, but I intend to be more prepared than the last time if they catch me off guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[94234] = { id = 94234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Shadow Goggles", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey! Watch where you're walking!", completion = "My new shadow goggles!\n\n<Without another word, the goblin tossed a handful of coins your way with one hand while the other swiped the item out of your grasp. The transaction was completed and his attention lost before you had a moment to process what happened.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94235] = { id = 94235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Gnomish Universal Remote", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Careful where you walk, Gizmo! This thing likes to activate when you least expect it, and we don't quite have a handle on where it can take you when we aren't actively manning the controls.", completion = "Seems we are in luck, the remote has arrived! Looks like you precalibrated it for us which, I'll admit, isn't ideal for this scenario.\n\nI should be able to reverse engineer it in no time. Then maybe, hopefully, I'll be able to take a much needed break. Feels like I've been stuck fumbling with this teleporter's controls for months on end!", sourceObjectiveStatus = "unverified-source-field" }
quests[94236] = { id = 94236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Big Bronze Bomb", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "You got the stuff?", completion = "Hey, there's the bomb I ordered!\n\nWell, one of them anyway. I needed a variety pack! You know, enough so I can test each one for effectiveness AND have a few leftover for my own needs!\n\nWell, whatever. Here's a cut of your cut, I'll give you the rest when you bring ME my full order!", sourceObjectiveStatus = "unverified-source-field" }
quests[94237] = { id = 94237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Crafted Solid Shot", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94238] = { id = 94238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Heavy Leather Ball", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94239] = { id = 94239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Fine Leather Pants", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Move along, please, and try not to draw attention to us.", completion = "Oh! The pants? Ah, I realized shortly after writing this that I needed a full set of clothes - new overalls included.\n\nIf it will get you out of my hair, I suppose I should honor the request. After all, you did make an arduous journey to find me.\n\nTake this, now please...\n\n<She gestured in a polite but firm shooing motion.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94240] = { id = 94240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Herbalist's Gloves", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94241] = { id = 94241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Dark Leather Tunic", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "WHAT???", completion = "Oh your timing is impeccable!\n\nCallahan! Your new shirt arrived. Hurry up and change so I can stop hearing about how itchy you are all the time.\n\nAnd for you, {race}. Here is your payment. Before you wander off, you should take a look at my wares now that you can afford 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[94242] = { id = 94242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Pilferer's Gloves", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94243] = { id = 94243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Heavy Quiver", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Need some work?", completion = "I--Hmm.\n\nI don't remember why I ordered this.\n\n<Ziz shrugs and tosses the quiver into a nearby pile of junk.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94244] = { id = 94244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Dark Leather Shoulders", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, what business do ye' have with ol' Narkk?", completion = "Thar be me shoulderpads, at last!\n\nEver had one of these squakers perch on your shoulder? Bet ye' haven't! Their claws, they hurt!\n\nNow they got a place to rest all day, and you have a heavier coinpurse!\n\n<Narkk eyes said coinpurse.>\n\nFor now!", sourceObjectiveStatus = "unverified-source-field" }
quests[94245] = { id = 94245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Barbaric Gloves", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94246] = { id = 94246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Red Whelp Gloves", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94247] = { id = 94247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Lesser Wizard's Robe", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The man stands at attention, peering over the mountainside toward Dalaran. He regards your presence with a subtle wave of a hand, beckoning you closer.>", completion = "<Alan speaks in a whisper.>\n\nDon't you think it is a little suspicious to be carrying elegant robes in broad daylight to a man garbed in dark leathers?\n\nWell, ahem, fortunately I am out here on behalf of the Kirin Tor, so there is no shady transaction about to take place. None at all.\n\nThe robe, please.", sourceObjectiveStatus = "unverified-source-field" }
quests[94248] = { id = 94248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Blue Overalls", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Oh! Please keep your voice down, we don't need to draw any further attention to ourselves.\n\nDo you have something for me?", completion = "The Blue Overalls! Thank goodness, I have a proper change of clothes.\n\nTake this, and please be on your way. I do not have time to chat, I must keep an eye on the farm and can't risk more distractions.", sourceObjectiveStatus = "unverified-source-field" }
quests[94249] = { id = 94249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Azure Silk Hood", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "AHHHH! Oh, it just a {race}.\n\nHi {race}!", completion = "It da hood me order-er-ed!\n\nMe forgot why wanted in first place, but me take anyway.\n\nHere, take shiny coin. It fell out of slime monster. Lots and lots of them!", sourceObjectiveStatus = "unverified-source-field" }
quests[94250] = { id = 94250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Small Silk Pack", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo! Is that pack for me?", completion = "Ha ha! Thanks, pal. I owe you.\n\n<Kzixx reaches into a Small Silk Pack already in his possession, filled to the brim with coin, and pulls out a fist full. He counts out a tiny fraction of his total wealth, and hands it to you.>\n\nThis should cover it. No take-backs!", sourceObjectiveStatus = "unverified-source-field" }
