quests[94253] = { id = 94253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Colorful Kilt", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94254] = { id = 94254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Greater Adept's Robe", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<Magus Tirth begins to cast Polymorph: Chicken on you.>", completion = "My new robe! Delightful!\n\nAt long last, I can don my robe AND my wizard hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[94255] = { id = 94255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Spider Silk Slippers", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo!", completion = "Are these my new boots?\n\n<Kixxle looks very excited, but it fades immediately upon setting his eyes upon them.>\n\nAh. I thought I had cancelled the order for slippers once I realized how foolish it would be to trudge around a swamp with my toes hanging out. I ordered a new pair of proper boots too, but they still haven't arrived yet.\n\nOh well, pleasure doing business with you. I'll keep these for later!", sourceObjectiveStatus = "unverified-source-field" }
