quests[94360] = { id = 94360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craftsman's Writ: Soul Pouch", sourceObjective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[94369] = { id = 94369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Zephras", description = "Ansirem has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir now that the wards that have hidden Zephras are down. If the Windlord chooses to attack us, we stand no chance to defend ourselves while we are here in his domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it.", sourceObjective = "Speak with Talaanis Shadowsong in Valanaar.", completion = "<Talaanis Shadowsong listens intently as you tell him of what transpired above the Shrine of Akir, and of Elaadrin's plan to leave Zephras Isle.>\n\nI need to reflect on this further, but looking at the upside, we have rid ourselves of Lorthuna and deprived the cult of their leader. Our home has not been invaded yet, and on the timeline of elemental demigods, it could be years... decades even, before Al'Akir deigns to turn his attention to us.\n\nThere is much to fear now, but much to celebrate as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[94373] = { id = 94373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Aye, the time's come, young shaman. Ye've grown stout and sturdy, like the stone beneath our boots. Takin' up the shaman's path shows ye've got the wisdom o' the mountain, even before ye've proven yerself.. Ye've the grit of stone to walk the earth's path. \n\nBut to earn its favor, ye must face it proper. South o' here, the Frostmane trolls live in a cave.\n\nBring me two of their necklaces they wear--crafted from the Iceclaw bears. Then we'll speak more of yer future.", sourceObjective = "Bring 2 Frostmane Bear Pendants to Teo Hammerstorm in Anvilmar.", progress = "Patience, lad, is the earth's finest virtue. It's seen mountains crumble and rivers carve valleys - slow and stubborn, like a true {race}. The earth calls to ye now, for trouble brews on the horizon. Return successful, and ye'll be one step closer to bein' whole. \n\nOthers may envy yer wisdom, but that's their burden to bear.", completion = "Well done, lad. Ye've proven yerself ready. Earth's the bedrock of all things. Strength, stamina, patience. It'll shield ye, but only if ye show it proper respect. Even stone can shift if slighted. Learn its ways, and ye'll grow wiser than most. Never forget the secrets it shares. \n\nI'll craft ye a sapta now - accept it, and ye'll walk the true path.", sourceObjectiveStatus = "unverified-source-field" }
quests[94374] = { id = 94374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Aye, sapta's a brew forged with magic, bindin' our spirit to the elements. Only a few shaman know the recipe, and it's nae for the weak-willed. Drink it, and ye will see what others can't. Hold true--it's only to be drunk in a sacred place.\n\nHead north to the Spirit Stone, tucked at the end of a hidden path up the mountain. Drink it there... see what the earth has to show ye.", sourceObjective = "Find the Spirit Stone and drink the Earth Sapta.\n\nProvided item:", completion = "Ah... {name}... the earth welcomes you, even in this frozen land. Bound in body and spirit, you'll walk forward knowing the mountains are your strength, the plains your patience, and the world your essence.\n\nTo pass this rite, stand humbly before the earth. The other elements are not so still - they clash and roar. Learn their dual nature, even here among the snow and stone.", sourceObjectiveStatus = "unverified-source-field" }
quests[94375] = { id = 94375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Earth", description = "Take this rough quartz from me and bring it to Teo Hammerstorm as proof o' our meeting. He will craft a totem for ye, and this pebble will be the heart o' it. As small as it may seem, ye will come to find that size does not matter, and that even the smallest o' things can outlast many others.\n\nBe patient, {name}. Remain strong. And seek wisdom. This is what earth asks o' ye. In the end, ye shall become one with the earth--respect it as it shall respect ye.", sourceObjective = "Bring the Rough Quartz to Teo Hammerstorm in Anvilmar.", progress = "Ahh, ye've returned. If ye have the stone, it means the mountain's chosen ye true. I'll give ye the totem it promised. But if ye've come empty-handed, off with ye! The path ain't for those who forget their way.", completion = "Well done! Know this - totems ain't just a mark of yer place among shamans. They're tools, a focus for spells tied to stone, soil, and other elements. As ye grow wiser, more o' the mountain's power will open to ye. The trainers will know when yer ready for more. But for now, take this totem, and let the ground speak through ye.", sourceObjectiveStatus = "unverified-source-field" }
quests[94411] = { id = 94411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meddlesome Mages", description = "Be warned, members of the High Order have been seen in the vicinity of the standing stones north of the village. We have warned them time and again to not meddle at our sacred sites, but they are growing more bold in pushing us. Prove your resolve to us by going to the standing stones and dispersing them.\n\nI am loathe to condone outright bloodshed, but do what you must to drive them off. Return to me when its done.", sourceObjective = "Slay 6 High Order Apprentices in Shen'dar Highlands.", completion = "Direct conflict with our shen'dorei brothers and sisters only weakens us as a people, but decisive action must at times be taken to prevent greater tragedy.\n\nThe mages of the High Order have zero regard for the consequences of their magical meddling. The forces that bind our island are fragile and vulnerable and all it could take is one thoughtless action to destroy our home.", sourceObjectiveStatus = "unverified-source-field" }
quests[94413] = { id = 94413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Magical Affront", description = "The recent emergence of the ley lines on the surface of Zephras has been profound for our order. We have more direct and tangible access to the energies that permeate this place and it has increased our understanding of said magic greatly.\n\nThe Windshapers, however, view these emergences as scars on the land that must be \"healed\". This is an affront to our order and is something we simply cannot abide.\n\nGo to the ley line in the forest to the southwest and drive off the Windshapers you find there.", sourceObjective = "Slay 6 Windshaper Novice Seers in Shen'dar Highlands.", completion = "Sometimes I find it hard to distinguish between the blind zealotry of the Al'Aketh cult, and the stubborn refusal of the Windshapers to change.\n\nIf they truly believed the winds would guide us, they should be sensing the direction the winds are blowing and flow with them rather than against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[94414] = { id = 94414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anchors of Zephras", description = "Greetings, young {name}. I often times come here to look upon the ancient anchor pylon. Gifts from the spirits of the winds, they bind and sustain our island. Of late however, their magic has grown unstable and inconsistent.\n\nThey suffer no distress I can see. Their splendor has not changed.\n\nIf you'd like, I can lend you my gift to look upon them yourself.", sourceObjective = "Speak with Halaan Hawk-Eye and borrow his gift to view the anchor pylon in the distance.", progress = "My gift is simple, and mundane. I cannot peer between worlds such as those with the skysight, nor can I draw upon the magic of the ley lines beneath Zephras like others can. But a gift it remains and I am grateful to have it.\n\nAppreciation of what you have is the key to happiness. Yearning for what you may have, or what you have lost, only leads to despair.", completion = "Thank you for taking a moment to share this with me. I will continue to watch over the grove, and ponder on the state of our homeland.", sourceObjectiveStatus = "unverified-source-field" }
quests[94427] = { id = 94427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "A key tenant of being a paladin is the pursuit of divinity. This is not the pursuit of godhood, but merely the pursuit of good itself, for good's sake. We've all arrived at this place due to tragedy of one form or another, and it would be easy to lose that grace that defined us as paladins in life.\n\nGo to the Undercity and seek out Tanis Alderwood in the Trade Quarter. They are in need, and they could benefit greatly from some grace.", sourceObjective = "Speak to Tanis Alderwood in the Undercity.", completion = "You... you are a {class}? Please, do not hurt me. I-I know I'm not supposed to be panhandling. I have no quarrel with you or your order. Leave me be, I beg you!", sourceObjectiveStatus = "unverified-source-field" }
quests[94434] = { id = 94434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "Wait, you want to... help? Why would a paladin want to help a beggar like me?\n\nWell, I suppose that you could be of some assistance. \n\nIts my wife you see. She, well... she's falling apart. I mean that literally. The apothecaries can stitch her back together right as rain, but they are about the Dark Lady's business and none are available to help. If you could perhaps bring me some fresh cloth then I could at least make her a wrapping to hold her together while we wait for the apothecaries.", sourceObjective = "Bring 10 Linen Cloth to Tanis Alderwood in the Undercity.", progress = "I hope that this is no imposition upon you, goodly {class}.", completion = "This is very kind of you, {class}. Very kind indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[94435] = { id = 94435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "I don't know why you'd go out of your way to help me, but I appreciate it. If someone sent you my way, tell them I appreciate them too. You'll always have a friend in Tanis Alderwood, {class}.", sourceObjective = "Return to Danitha Morr at Bandarion Keep.", completion = "You have done well, {name}. It was a small thing, but even small acts of service such as this may help strengthen our connection to the light.\n\nThe Dark Lady and many in her service mistrust us. Some even conspire against us, but we will visit their skepticism and fear with courage and righteousness. We will show them that we are members of the Forsaken and we are willing to do our part, be it large or small, to help our people prosper once again.\n\nTake this symbol, you will need it for what comes next.", sourceObjectiveStatus = "unverified-source-field" }
quests[94436] = { id = 94436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "It's time to demonstrate your ability to channel one of the light's greatest gifts.\n\nThe item I just gave you is called the Symbol of Life. Take care, as it may cause you some discomfort to handle a talisman of the light such as this. The light may be anathema to the force that created us, but it is still our guide and ally. The pain reminds us of this.\n\nGo see Deathguard Billmuth downstairs. He just arrived and he has petitioned us for aid. Show him and the Forsaken what a true paladin can do.", sourceObjective = "Speak with Deathguard Billmuth at Bandarion Keep.\n\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.", completion = "So you'll help me, then? Good, good. I'll admit I'm not proud of resorting to... well, resorting to asking paladins for aid. The priests waved me away and you might be my friend's only chance.\n\nPlease, help me.", sourceObjectiveStatus = "unverified-source-field" }
quests[94438] = { id = 94438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "Falgan and I were sent on a mission to scout out scarlet activity in Venomweb Vale. We managed to sneak close enough to one of their camps to hear about new orders involving an attack on Brill. Before we could decide what to do next, I stepped on a twig and the noise alerted them to us.\n\nFalgan yelled at me to run, so I ran. By the time I realized he wasn't with me, I was halfway to Brill. That brave idiot probably stayed behind to hold them off for me.\n\nPlease, find my friend and help him if you can.", sourceObjective = "Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale. \n\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.", completion = "I'm... back? And saved by a {class} no less? I see you carry a Symbol of Life. I've not seen one of those since... well, since before the war when Lordaeron was a very different place. I can only assume you are here to help. Billmuth and I were sent here to scout out the scarlet activity here, and we found out that they are planning some kind of attack.\n\nIf you would be willing to help more, there may yet be more than you can do to help the Forsaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[94440] = { id = 94440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "These Scarlet Crusaders often carry satchels with their deployment orders. We know an attack is coming, but if we can recover their orders, we can warn the rest of the Deathguard and prepare an ambush. \n\nYou are clearly an impressive paladin. Kill these scarlet animals and retrieve a copy of their orders and bring them back to Deathguard Billmuth. He'll take it from there.", sourceObjective = "Retrieve the Scarlet Crusade Attack Plans from the Scarlet Crusaders at Venomweb Vale, and return to Deathguard Billmuth at Tyr's Watch.", progress = "What news of Deathguard Falgan?", completion = "Thank you for saving my friend,{name}. I will take these plans back to my commander and we will give those crusaders a welcoming they won't forget.\n\nI know that many among our people mistrust you paladins, but its clear to me that you are Forsaken through and through. I won't forget this, and I'll make sure others know of what you did here today.", sourceObjectiveStatus = "unverified-source-field" }
quests[94441] = { id = 94441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Divinity", description = "Please give my thanks to Danitha Morr and tell her that the rest of the Deathguard will hear about the service that the paladins of Tyr's Watch performed for us. \n\nYou have a lot of promise as a paladin, and I am proud to have those like you among the ranks of the Forsaken. Dark Lady watch over you, {name}.", sourceObjective = "Speak with Danitha Morr in the keep at Bandarion Keep.", completion = "The Symbol of Life is only able to be used by a {class} who is ready to make use of one of the light's greatest blessings. I'm proud to count you among us, and I now bestow upon you the gift of redemption. With this you will be able to resurrect your fallen companions. Use this new boon wisely.\n\nYou have done well for both the Forsaken as well as the paladins of Tyr's Watch. Any steps we can take to win the hearts and minds of our fellow Forsaken is well worth the effort. Go with the light, {name}.", sourceObjectiveStatus = "unverified-source-field" }
